function analyzeNotes(notes){const paragraphs=String(notes).split(/\n+|(?<=[.!?])\s+/).map(s=>s.trim()).filter(Boolean);const matches=Object.entries(concepts).map(([id,c])=>({id,name:c.name,evidence:paragraphs.filter(p=>c.pattern.test(p)).slice(0,2).join(' ').slice(0,650)})).filter(x=>x.evidence);const unsupported=[];const flags=[[/FIFO|LIFO|inventory|cost of goods sold/i,'Inventory valuation and cost of goods sold'],[/bond|amortization of.*discount|effective.interest/i,'Bonds and effective-interest amortization'],[/declining.balance|units.of.production/i,'Depreciation methods other than straight-line'],[/bank reconcili|outstanding check|deposit in transit/i,'Bank reconciliation'],[/closing entr|income summary/i,'Closing entries'],[/sales tax|VAT/i,'Sales tax'],[/bad debt|allowance for doubtful/i,'Bad-debt estimates'],[/dividend|common stock|retained earnings/i,'Corporate equity'],[/cash flow statement|statement of cash flows/i,'Full cash-flow statements']];for(const [p,label]of flags)if(p.test(notes))unsupported.push(label);return {matches,unsupported};}
