function pendingDecision(r){if(!r.assignment.interactive)return null;const stage=r.stage||0;return r.assignment.interactive.controls.some(c=>D.controlStage(r.assignment,c)===stage)&&!(r.decidedStages||[...(r.decidedMonths||[0]).map(m=>m*2)]).includes(stage)?stage:null;}
function decisionControls(r){return r.assignment.interactive.controls.filter(c=>D.controlStage(r.assignment,c)===(r.stage||0));}
function pendingMonth(r){const stage=pendingDecision(r);return stage===null?null:Math.floor(stage/2);}
function availableEvents(r){const pending=pendingDecision(r);return r.assignment.version>=2?r.scenario.events.filter(e=>e.stage<=(r.stage||0)&&(pending===null||e.stage<pending)):(r.advanced?r.scenario.events:r.scenario.events.slice(0,1));}

function topic(a){if(a.version===3)return {name:'Course assignment',goal:a.objectives.join(' '),effect:'Report the financial results using your accounts.'};return (a.version===2?concepts:topics)[a.topic];}
