 const names=b.accounts.map(x=>x?.name);if(new Set(names).size!==names.length||b.accounts.some(x=>typeof x.name!=='string'||!x.name.trim()||x.name.length>60||['__proto__','constructor','prototype'].includes(x.name)||!types.includes(x.type))||!names.includes('Cash'))return false;
 const rows=rs=>Array.isArray(rs)&&rs.length>=2&&rs.length<=8&&rs.every(x=>x&&typeof x.account==='string'&&names.includes(x.account)&&typeof x.debit==='number'&&typeof x.credit==='number'&&Number.isFinite(x.debit)&&Number.isFinite(x.credit)&&x.debit>=0&&x.credit>=0&&x.debit<=1e6&&x.credit<=1e6&&Math.abs(x.debit*100-Math.round(x.debit*100))<1e-6&&Math.abs(x.credit*100-Math.round(x.credit*100))<1e-6&&((x.debit>0)!==(x.credit>0)))&&Math.round(rs.reduce((n,x)=>n+x.debit-x.credit,0)*100)===0;
 if(b.opening.length&& !rows(b.opening))return false;
 return b.paths.every((p,i)=>p&&p.id===String(i)&&typeof p.label==='string'&&p.label.length<=100&&typeof p.description==='string'&&p.description.length<=1200&&Array.isArray(p.events)&&p.events.length>=2&&p.events.length<=18&&new Set(p.events.map(e=>e.id)).size===p.events.length&&p.events.some(e=>e.stage===0)&&p.events.some(e=>e.stage===finalStage(a))&&p.events.every(e=>typeof e.id==='string'&&/^[a-z0-9-]{1,60}$/.test(e.id)&&typeof e.title==='string'&&e.title.length<=120&&Number.isInteger(e.stage)&&e.stage>=0&&e.stage<=finalStage(a)&&e.date>=day(a,1)&&e.date<=finalDate(a)&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&!Number.isNaN(Date.parse(e.date))&&e.document&&typeof e.document.issuer==='string'&&e.document.issuer.length<=120&&typeof e.document.status==='string'&&e.document.status.length<=50&&Array.isArray(e.document.fields)&&e.document.fields.length>=3&&e.document.fields.length<=12&&e.document.fields.every(f=>typeof f.label==='string'&&f.label.length<=100&&typeof f.value==='string'&&f.value.length<=500)&&(Array.isArray(e.lines)&&e.lines.length===0||rows(e.lines))))&&a.conceptCheck&&typeof a.conceptCheck.prompt==='string'&&a.conceptCheck.prompt.length<=400&&Array.isArray(a.conceptCheck.options)&&a.conceptCheck.options.length===3&&a.conceptCheck.options.every(x=>typeof x==='string'&&x.length<=400)&&[0,1,2].includes(a.conceptCheck.correct)&&typeof a.conceptCheck.feedback==='string'&&a.conceptCheck.feedback.length<=1000;
