function generatedIssues(a){const issues=[],b=a.blueprint;if(!b)return ['Missing blueprint'];if(!Array.isArray(a.source)||a.source.some(x=>!x||typeof x.evidence!=='string'||!a.notes.includes(x.evidence)))issues.push('Course citations must quote the notes exactly');if(!Array.isArray(a.objectives)||a.objectives.length<1||a.objectives.length>6)issues.push('Use 1–6 objectives');if(!Array.isArray(b.accounts)||b.accounts.length<3||b.accounts.length>24||new Set(b.accounts.map(x=>x.name)).size!==b.accounts.length)issues.push('Chart of accounts must have 3–24 unique accounts');if(!b.accounts?.some(x=>x.name==='Cash'))issues.push('Cash account missing');const names=b.accounts?.map(x=>x.name)||[];const inspectRows=(rows,label)=>{if(Array.isArray(rows)&&rows.length===0)return;if(!Array.isArray(rows)||rows.length<2||rows.length>8){issues.push(label+' needs 2–8 lines for a transaction');return;}if(rows.some(x=>!names.includes(x.account)))issues.push(label+' uses an account outside the chart');if(rows.some(x=>typeof x.debit!=='number'||typeof x.credit!=='number'||x.debit<0||x.credit<0||((x.debit>0)===(x.credit>0))))issues.push(label+' needs one positive side per line');if(Math.abs(rows.reduce((n,x)=>n+x.debit-x.credit,0))>.005)issues.push(label+' does not balance');};if(b.opening?.length)inspectRows(b.opening,'Opening balances');if(!Array.isArray(b.paths)||b.paths.length!==3)issues.push('Exactly three plans required');for(const [i,p]of (b.paths||[]).entries()){if(p.id!==String(i))issues.push('Plan IDs must be ordered 0,1,2');if(!Array.isArray(p.events)||p.events.length<2||p.events.length>18)issues.push('Each plan needs 2–18 records');if(!p.events?.some(e=>e.stage===0)||!p.events?.some(e=>e.stage===finalStage(a)))issues.push('Each plan needs setup and period-end records');for(const e of p.events||[]){if(e.date<day(a,1)||e.date>finalDate(a))issues.push('Record date outside selected month');if(!Array.isArray(e.document?.fields)||e.document.fields.length<3||e.document.fields.length>12)issues.push('Records need 3–12 source facts');inspectRows(e.lines,'Expected entry');}}return [...new Set(issues)].slice(0,6).length?[...new Set(issues)].slice(0,6):['A field exceeded the assignment format or monetary limits'];}
function generatedBalances(scenario,entries){const b=Object.fromEntries(scenario.accountList.map(x=>[x,0]));for(const x of scenario.openingBalances||[])b[x.account]+=x.debit-x.credit;for(const e of Object.values(entries))for(const x of e.rows)b[x.account]+=Number(x.debit||0)-Number(x.credit||0);return Object.fromEntries(Object.entries(b).map(([k,v])=>[k,cents(v)]));}
