function neutralizeBusinessText(text){return String(text??'').replace(/\byour\s+(?:coffee\s*(?:shop|company|business)|cleaning\s*(?:company|business|service)|bakery|design studio|bike repair (?:shop|business)|plant shop|pet grooming (?:business|salon)|photography studio|fitness studio|bookshop)\b/gi,'{{business}}').replace(/\b(?:coffee\s*(?:shop|company|business)|cleaning\s*(?:company|business|service)|bakery|design studio|bike repair shop|plant shop|pet grooming salon|photography studio|fitness studio|bookshop)\b/gi,'{{type}}').replace(/\b(?:cleaning supplies|coffee beans and cups|coffee beans, cups, and filters)\b/gi,'{{supplies}}');}
